import { Component } from '@angular/core';
import { AdminService } from '../../../services/admin.service';
import { AuthService } from '../../../services/auth.service';

@Component({
  selector: 'app-admin-header',
  templateUrl: './admin-header.component.html',
  styleUrls: ['./admin-header.component.css']
})
export class AdminHeaderComponent {
  constructor(
    private adminService: AdminService,
    private authService: AuthService
  ) {}

  toggleSidebar(): void {
    this.adminService.toggleSidebar();
  }

  logout(): void {
    this.authService.logout().subscribe({
      next: () => {
        // Navigation được xử lý trong AuthService
      },
      error: () => {
        // Nếu logout API fail, vẫn clear local và redirect
        this.authService['clearUser']();
        window.location.href = '/login';
      }
    });
  }
}
<header class="admin-header">
  <div class="header-left">
    <button class="sidebar-toggle" (click)="toggleSidebar()" title="Thu gọn/Mở rộng menu">
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M3 12H21M3 6H21M3 18H21" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
      </svg>
    </button>
    <h1 class="header-title">Trang chủ</h1>
  </div>
  <div class="header-right">
    <div class="user-info">
      <span class="user-name">Admin</span>
      <div class="user-avatar">A</div>
    </div>
    <button class="logout-btn" (click)="logout()" title="Đăng xuất">
      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>
      <span>Đăng xuất</span>
    </button>
  </div>
</header>
